package io.invenlio.inventory;
import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.Timestamp;import java.time.Instant;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class InventoryPostingService implements InventoryPosting{
 private static final Set<String> STORAGE=Set.of("AISLE","RACK","SHELF","BIN","FLOOR","PALLET_POSITION");private final JdbcTemplate db;private final CatalogInventoryLookup catalog;private final WarehouseAvailability warehouses;private final TraceabilityService trace;
 InventoryPostingService(JdbcTemplate d,CatalogInventoryLookup c,WarehouseAvailability w,TraceabilityService t){db=d;catalog=c;warehouses=w;trace=t;}
 @Override@Transactional public UUID receive(UUID tenant,String actor,String key,List<Stock> lines){requireKey(key);if(lines==null||lines.isEmpty())throw error("RECEIPT_LINES_REQUIRED");lock(tenant+":inventory-idem:"+key);UUID prior=existing(tenant,key,fingerprint(lines,null));if(prior!=null)return prior;for(Stock s:lines)validate(tenant,s,"RECEIVING");UUID movement=movement(tenant,"GOODS_RECEIPT",key,fingerprint(lines,null),actor);int sequence=0;for(Stock s:lines){if(s.serialId()!=null){lock(tenant+":serial:"+s.serialId());BigDecimal global=db.queryForObject("SELECT COALESCE(sum(on_hand_quantity),0) FROM inventory_balances WHERE tenant_id=? AND serial_id=?",BigDecimal.class,tenant,s.serialId());if(global.signum()>0)throw error("SERIAL_ALREADY_ON_HAND");}post(tenant,movement,sequence++,s,s.quantity());}return movement;}
 @Override@Transactional public UUID relocate(UUID tenant,String actor,String key,Stock s,UUID destination){requireKey(key);validate(tenant,s,"RECEIVING");var dest=warehouses.findUsableLocation(tenant,s.warehouseId(),destination).orElseThrow(()->error("DESTINATION_LOCATION_INVALID"));if(!STORAGE.contains(dest.type()))throw error("DESTINATION_NOT_STORAGE_ELIGIBLE");String fp=fingerprint(List.of(s),destination);lock(tenant+":inventory-idem:"+key);UUID prior=existing(tenant,key,fp);if(prior!=null)return prior;if(s.serialId()!=null)lock(tenant+":serial:"+s.serialId());List<String> locks=new ArrayList<>(List.of(dimension(tenant,s),dimension(tenant,new Stock(s.variantId(),s.warehouseId(),destination,s.lotId(),s.serialId(),s.quantity()))));Collections.sort(locks);locks.forEach(this::lock);UUID movement=movement(tenant,"PUT_AWAY",key,fp,actor);post(tenant,movement,0,s,s.quantity().negate());post(tenant,movement,1,new Stock(s.variantId(),s.warehouseId(),destination,s.lotId(),s.serialId(),s.quantity()),s.quantity());return movement;}
 private void validate(UUID tenant,Stock s,String requiredType){if(s==null||s.quantity()==null||s.quantity().signum()<=0||s.quantity().scale()>6||s.quantity().precision()>19)throw error("INVALID_INVENTORY_QUANTITY");var variant=catalog.findInventoryVariant(tenant,s.variantId()).orElseThrow(()->error("VARIANT_NOT_INVENTORY_ELIGIBLE"));if(Set.of("DRAFT","ARCHIVED").contains(variant.status()))throw error("VARIANT_NOT_INVENTORY_ELIGIBLE");if(variant.discrete()&&s.quantity().stripTrailingZeros().scale()>0)throw error("INVALID_INVENTORY_QUANTITY");trace.resolve(tenant,s.variantId(),s.lotId(),s.serialId(),variant.trackingMode());if(s.serialId()!=null&&s.quantity().compareTo(BigDecimal.ONE)!=0)throw error("INVALID_SERIAL_QUANTITY");var location=warehouses.findUsableLocation(tenant,s.warehouseId(),s.locationId()).orElseThrow(()->error("LOCATION_NOT_INVENTORY_ELIGIBLE"));if(requiredType!=null&&!requiredType.equals(location.type()))throw error("RECEIVING_LOCATION_REQUIRED");}
 private void post(UUID tenant,UUID movement,int sequence,Stock s,BigDecimal delta){var variant=catalog.findInventoryVariant(tenant,s.variantId()).orElseThrow();Instant now=Instant.now();db.update("INSERT INTO inventory_balances(id,tenant_id,variant_id,warehouse_id,location_id,on_hand_quantity,unit_code,updated_at,version,lot_id,serial_id) VALUES(?,?,?,?,?,0,?,?,0,?,?) ON CONFLICT DO NOTHING",UUID.randomUUID(),tenant,s.variantId(),s.warehouseId(),s.locationId(),variant.baseUnit(),Timestamp.from(now),s.lotId(),s.serialId());int n=db.update("UPDATE inventory_balances SET on_hand_quantity=on_hand_quantity+?,updated_at=?,version=version+1 WHERE tenant_id=? AND variant_id=? AND warehouse_id=? AND location_id=? AND lot_id IS NOT DISTINCT FROM ? AND serial_id IS NOT DISTINCT FROM ? AND on_hand_quantity+?>=reserved_quantity",delta,Timestamp.from(now),tenant,s.variantId(),s.warehouseId(),s.locationId(),s.lotId(),s.serialId(),delta);if(n!=1)throw error("INSUFFICIENT_ON_HAND");db.update("INSERT INTO inventory_ledger_entries(id,tenant_id,movement_id,sequence,variant_id,warehouse_id,location_id,quantity_delta,unit_code,occurred_at,recorded_at,lot_id,serial_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),tenant,movement,sequence,s.variantId(),s.warehouseId(),s.locationId(),delta,variant.baseUnit(),Timestamp.from(now),Timestamp.from(now),s.lotId(),s.serialId());}
 private UUID movement(UUID tenant,String type,String key,String fp,String actor){UUID id=UUID.randomUUID();Instant now=Instant.now();db.update("INSERT INTO inventory_movements(id,tenant_id,movement_type,idempotency_key,request_fingerprint,reason_code,actor_subject,occurred_at,recorded_at) VALUES(?,?,?,?,?,?,?,?,?)",id,tenant,type,key,fp,type,actor,Timestamp.from(now),Timestamp.from(now));return id;}private UUID existing(UUID tenant,String key,String fp){var x=db.query("SELECT id,request_fingerprint FROM inventory_movements WHERE tenant_id=? AND idempotency_key=?",(r,n)->Map.entry((UUID)r.getObject(1),r.getString(2)),tenant,key);if(x.isEmpty())return null;if(!x.getFirst().getValue().equals(fp))throw error("IDEMPOTENCY_KEY_REUSED");return x.getFirst().getKey();}private void lock(String v){db.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,v);}private static void requireKey(String k){if(k==null||k.isBlank()||k.length()>128)throw error("IDEMPOTENCY_KEY_REQUIRED");}private static String dimension(UUID t,Stock s){return t+":"+s.variantId()+":"+s.warehouseId()+":"+s.locationId()+":"+s.lotId()+":"+s.serialId();}private static String fingerprint(List<Stock> lines,UUID destination){try{String value=lines.stream().map(Object::toString).sorted().reduce("",(a,b)->a+"|"+b)+"|"+destination;return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static InventoryException error(String c){return new InventoryException(c,c.replace('_',' ').toLowerCase());}
}
